css:
/* this prompt is a purpose, not an idea, so it wears the purpose colour */
.thesis.lit .key{background:var(--eff-bg);color:var(--eff-tx)}
.centre{background:var(--eff-bg);color:var(--eff-tx);border-color:var(--eff-tx)}
.centre span{color:var(--eff-tx)}
.card .what.land{color:var(--eff-tx);background:var(--eff-bg)}
/* agreeing is not a role, so it takes a tick rather than a colour */
.node.agree{border-color:var(--ink);background:#fff;color:var(--ink)}
